import React from 'react';
import { AbsoluteFill, interpolate, useCurrentFrame } from 'remotion';
import { COLORS, EASINGS } from '../../brand';
import { FONT_BODY, FONT_MONO } from '../../fonts';
import { CLAMP } from '../../lib/kit';
import { CaptionTrack, CoverImage, HookTitle, ProgressBar, SAFE, ShortBg, ToolCard, Watermark, secToFrame } from '../../lib/shorts';
import { WORDS } from './words';

// short-127: generated by the daily batch. Cover held at frame 0; closes on the cover.
export const compositionConfig = { id: 'Short127', durationInSeconds: 32.9, fps: 30, width: 1080, height: 1920 };

const FadeOut: React.FC<{ at: number; children: React.ReactNode }> = ({ at, children }) => {
  const frame = useCurrentFrame();
  const op = 1 - interpolate(frame, [at - 8, at + 2], [0, 1], { ...CLAMP, easing: EASINGS.easeIn });
  return <AbsoluteFill style={{ opacity: op }}>{children}</AbsoluteFill>;
};

const Line: React.FC<{ k: string; v: string; good?: boolean; bad?: boolean }> = ({ k, v, good, bad }) => (
  <div style={{ display: 'flex', justifyContent: 'space-between', gap: 24, fontFamily: FONT_MONO, fontSize: 32 }}>
    <span style={{ color: COLORS.d400 }}>{k}</span>
    <span style={{ color: bad ? COLORS.danger : good ? COLORS.signalAlt : COLORS.d300, fontWeight: good || bad ? 700 : 400 }}>{v}</span>
  </div>
);
const Panel: React.FC<{ children: React.ReactNode }> = ({ children }) => (
  <div style={{ background: COLORS.d900, borderRadius: 12, padding: '24px 26px', display: 'flex', flexDirection: 'column', gap: 16 }}>{children}</div>
);

const Short127: React.FC = () => {
  const frame = useCurrentFrame();
  const CTA = secToFrame(29.3);
  const ctaOp = interpolate(frame, [CTA, CTA + 12], [0, 1], { ...CLAMP, easing: EASINGS.easeOut });
  const lines = [{text: "AGENT RUNTIME"}, {text: "8\u00a2 AN HOUR", accent: true}];
  return (
    <AbsoluteFill>
      <ShortBg />
      <FadeOut at={secToFrame(3.0)}>
        <CoverImage src="projects/short-127/cover.png" out={secToFrame(3.0) - 10} />
        <HookTitle hold onDark kicker="CLAUDE API" lines={lines} />
      </FadeOut>
      <FadeOut at={secToFrame(5.3)}>
        <ToolCard name="Claude Managed Agents" tagline="Tokens plus runtime." chip="AGENTS" at={secToFrame(3.0) - 2} chipColor={COLORS.accent2}>
          <Panel>
            <Line k="billed on" v="tokens + runtime" />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={secToFrame(8.8)}>
        <ToolCard name="Session runtime" tagline="Per session-hour." chip="$0.08" at={secToFrame(5.3) - 2}>
          <Panel>
            <Line k="runtime" v="$0.08 / hour" good />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={secToFrame(11.8)}>
        <ToolCard name="The clock runs when" tagline="Status: running." chip="RUNNING" at={secToFrame(8.8) - 2} chipColor={COLORS.accent2}>
          <Panel>
            <Line k="status" v="running" />
            <Line k="billed" v="yes" bad />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={secToFrame(13.7)}>
        <ToolCard name="Idle time" tagline="Not counted." chip="FREE" at={secToFrame(11.8) - 2}>
          <Panel>
            <Line k="status" v="idle" />
            <Line k="billed" v="$0.00" good />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={secToFrame(16.9)}>
        <ToolCard name="Waiting on you" tagline="Next message." chip="FREE" at={secToFrame(13.7) - 2}>
          <Panel>
            <Line k="waiting for" v="your message" />
            <Line k="billed" v="$0.00" good />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={secToFrame(20.4)}>
        <ToolCard name="Waiting on a tool" tagline="Confirmation." chip="FREE" at={secToFrame(16.9) - 2}>
          <Panel>
            <Line k="waiting for" v="tool confirm" />
            <Line k="billed" v="$0.00" good />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={secToFrame(26.0)}>
        <ToolCard name="10 minutes of work" tagline="In a whole afternoon." chip="1¢" at={secToFrame(20.4) - 2}>
          <Panel>
            <Line k="0.08 x 10/60" v="$0.013" good />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={secToFrame(29.3)}>
        <ToolCard name="Tokens bill separately" tagline="Normal model rates." chip="TOKENS" at={secToFrame(26.0) - 2} chipColor={COLORS.accent2}>
          <Panel>
            <Line k="tokens" v="model rates" />
            <Line k="runtime" v="+ $0.08 / hr" />
          </Panel>
        </ToolCard>
      </FadeOut>
      <AbsoluteFill style={{ opacity: ctaOp }}>
        <CoverImage src="projects/short-127/cover.png" at={CTA} />
        <HookTitle hold onDark at={CTA} kicker="CLAUDE API" lines={lines} />
        <div style={{ position: 'absolute', left: SAFE.side, right: SAFE.side, top: SAFE.top + 520, textAlign: 'center', fontFamily: FONT_BODY, fontWeight: 600, fontSize: 44, color: 'rgba(255,255,255,0.82)' }}>
          Claude's agent runtime: 8¢ an hour.
        </div>
      </AbsoluteFill>
      <CaptionTrack words={WORDS} />
      <Watermark at={12} />
      <ProgressBar />
    </AbsoluteFill>
  );
};
export default Short127;
